import{_ as t,o as a,c as n,ae as r}from"./chunks/framework.1Lna8NcP.js";const u=JSON.parse('{"title":"ADR-010 — At-Rest Encryption","description":"","frontmatter":{},"headers":[],"relativePath":"adr/010-at-rest-encryption.md","filePath":"adr/010-at-rest-encryption.md"}'),o={name:"adr/010-at-rest-encryption.md"};function s(i,e,d,l,c,p){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-010-—-at-rest-encryption" tabindex="-1">ADR-010 — At-Rest Encryption <a class="header-anchor" href="#adr-010-—-at-rest-encryption" aria-label="Permalink to &quot;ADR-010 — At-Rest Encryption&quot;">​</a></h1><p><strong>Status:</strong> Accepted<br><strong>Date:</strong> 2026-04-19</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Libertas stores sensitive financial data locally in a SQLite database. The file is unprotected by default — if a machine is compromised or the disk is imaged, all account names, transaction descriptions, holdings, and API keys are readable as plaintext.</p><p>The goal is to make the database unreadable without the user&#39;s key, while keeping the app fully functional and not requiring cloud infrastructure.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Implement field-level AES-256-GCM encryption on all TEXT columns containing PII or financial data. Numeric columns (amounts, prices, balances) are left unencrypted — encrypting floats would break SQL aggregations that power dashboards and charts.</p><p>Two key storage modes are supported:</p><ul><li><strong>macOS Keychain (default):</strong> A 32-byte random key is generated once and stored in the system Keychain. macOS protects it with the user&#39;s login or Touch ID. The app loads it automatically on startup — no user action required after initial setup.</li><li><strong>Passphrase (maximum security):</strong> The user provides a passphrase. Argon2id derives a 32-byte key from the passphrase + a stored salt. The key exists only in memory during the session. If lost, the data cannot be recovered.</li></ul><h2 id="encrypted-columns" tabindex="-1">Encrypted columns <a class="header-anchor" href="#encrypted-columns" aria-label="Permalink to &quot;Encrypted columns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model</th><th>Columns</th></tr></thead><tbody><tr><td>Institution</td><td>name, export_url, notes</td></tr><tr><td>Account</td><td>name, external_id</td></tr><tr><td>Holding</td><td>symbol</td></tr><tr><td>Transaction</td><td>symbol, description</td></tr><tr><td>RealEstate</td><td>address</td></tr><tr><td>Setting</td><td>value</td></tr></tbody></table><p>Columns intentionally left unencrypted: all Float/Integer columns (amount, price, quantity, balance, rate), dates, foreign keys, status fields, and JSON blobs containing only structural metadata.</p><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to &quot;Implementation&quot;">​</a></h2><p>A custom SQLAlchemy <code>TypeDecorator</code> (<code>EncryptedText</code>) wraps <code>Text</code>. On write it encrypts and prefixes with <code>enc1:</code>. On read it detects the prefix and decrypts. Rows written before encryption was enabled pass through unchanged, and are encrypted on their next write.</p><p>The active key is held in a module-level variable in memory. It is never written to disk (passphrase mode) or written in recoverable form (keychain mode stores only the key, not the passphrase).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Database file is unreadable without the key — stolen disk yields no financial data</li><li>No schema migration required — <code>EncryptedText</code> maps to <code>Text</code> at the SQLite level</li><li>Passphrase mode: losing the passphrase = permanent data loss (by design)</li><li>SQL <code>LIKE</code>, <code>ORDER BY</code>, and range queries on encrypted columns no longer work — acceptable since all filtering happens in Python after decryption</li><li>Claude never touches the raw database — it receives only decrypted query results passed in the API call</li></ul>',17)])])}const m=t(o,[["render",s]]);export{u as __pageData,m as default};
